do $$ declare t text; c record; begin foreach t in array array['client_packages', 'package_presets'] loop for c in select con.conname from pg_constraint con where con.conrelid = ('public.' || t)::regclass and con.contype = 'c' and pg_get_constraintdef(con.oid) like '%posting_mode%' and pg_get_constraintdef(con.oid) like '%per_week%' and pg_get_constraintdef(con.oid) not like '%videos_per_week%' loop execute format('alter table public.%I drop constraint %I', t, c.conname); end loop; execute format( 'alter table public.%I add constraint %I check (posting_mode in (''weekdays'', ''daily'', ''per_week'', ''alternate''))', t, t || '_posting_mode_check' ); end loop; end $$;
